/**
 * generated by stackra gen from src/routes/**\/*.route.ts (layout, tab, presentation, auth, header,
 * permission, flag, prefetch, document), src/routes/tabs.layout.ts (kind, guard, bar options) and
 * src/config/theming.config.ts (liquidGlass) — do not edit
 * Purpose: the React Navigation 7 tree: the signed-in root native stack (the tabs layout plus every
 *          `presentation` route with `auth: true` and no layout), one native stack per tab under
 *          the native tab bar, and the signed-out stack (`auth: false`). Header presets come from
 *          theming (`liquidGlass`). `toScreen(Route)` warms the route's `prefetch` queries,
 *          resolves its `document` through the experience adapter and validates `params` before the
 *          page mounts.
 * Boundary: code-based routes (ADR 0061: a hand-written tree is banned). Titles are translated here
 *           because the native header draws them. A route whose permission the actor lacks, or
 *           whose flag is off for the tenant, is not registered, so a deep link to it lands on the
 *           tab root. The layout's `guard` runs before any child.
 * Runtime: react-native
 */
import { createNativeBottomTabNavigator } from "@bottom-tabs/react-navigation";
import {
  createNativeStackNavigator,
  type NativeStackNavigationOptions,
} from "@react-navigation/native-stack";
import { useFlag } from "@stackra/feature-flags/react";
import { useTranslation } from "@stackra/i18n/react";
import { usePermission } from "@stackra/iam/react";
import { useSession } from "@stackra/identity/react";
import { toScreen, useLayoutGuard } from "@stackra/navigation/native";
import { Icons } from "@stackra/ui/icons";
import { useThemeColor } from "@stackra/ui/native";
import { Platform } from "react-native";
import { SessionStatus } from "@stackra/identity";
import { TabsLayout } from "#src/routes/tabs.layout";
import { Commerce } from "#stackra/clients";
import { Flags } from "#stackra/flags";
import { I18n } from "#stackra/i18n";
import { routeTable } from "#stackra/route-table";
import type { RouteParams } from "#stackra/routes";

const ios = Platform.OS === "ios";
/** theming.liquidGlass: transparent header on iOS, no shadow, minimal back button. */
const glass: NativeStackNavigationOptions = {
  headerTransparent: ios,
  headerShadowVisible: false,
  headerBackButtonDisplayMode: "minimal",
};
/** tabs.layout.ts largeTitles. */
const largeTitle: NativeStackNavigationOptions = {
  ...glass,
  headerLargeTitle: ios,
  headerLargeTitleShadowVisible: false,
};
/** Presentation.FormSheet. */
const formSheet: NativeStackNavigationOptions = {
  presentation: ios ? "formSheet" : "modal",
  sheetAllowedDetents: [0.75, 1],
  sheetGrabberVisible: true,
  headerShown: !ios,
};
/** Presentation.FullScreenModal. */
const fullScreenModal: NativeStackNavigationOptions = {
  presentation: "fullScreenModal",
  headerTransparent: true,
  headerShadowVisible: false,
};

const Root = createNativeStackNavigator<RouteParams & { tabs: undefined }>();
const SignedOut = createNativeStackNavigator<Pick<RouteParams, "sign_in">>();
const Tabs = createNativeBottomTabNavigator<{
  "tab:home": undefined;
  "tab:orders": undefined;
  "tab:settings": undefined;
}>();
const HomeStack = createNativeStackNavigator<Pick<RouteParams, "home">>();
const OrdersStack = createNativeStackNavigator<Pick<RouteParams, "orders">>();
const SettingsStack = createNativeStackNavigator<Pick<RouteParams, "settings">>();

function HomeTab() {
  const { t } = useTranslation();
  return (
    <HomeStack.Navigator screenOptions={largeTitle}>
      <HomeStack.Screen
        name="home"
        component={toScreen(routeTable.home)}
        options={{ title: t(I18n.mobile.home.title) }}
      />
    </HomeStack.Navigator>
 );
}

function OrdersTab() {
  const { t } = useTranslation();
  return (
    <OrdersStack.Navigator screenOptions={largeTitle}>
      <OrdersStack.Screen
        name="orders"
        component={toScreen(routeTable.orders)}
        options={{ title: t(I18n.mobile.orders.title) }}
      />
    </OrdersStack.Navigator>
 );
}

function SettingsTab() {
  const { t } = useTranslation();
  return (
    <SettingsStack.Navigator screenOptions={largeTitle}>
      <SettingsStack.Screen
        name="settings"
        component={toScreen(routeTable.settings)}
        options={{ title: t(I18n.mobile.settings.title) }}
      />
    </SettingsStack.Navigator>
 );
}

/**
 * tabs.layout.ts: native tabs, minimize on scroll, sidebar on iPad. The tabs are the routes that
 * declare `tab: { order, icon, label }`, sorted by `order`; a tab the actor may not read is hidden.
 */
function TabsShell() {
  const { t } = useTranslation();
  const can = usePermission();
  const [accent] = useThemeColor(["accent"]);
  return (
    <Tabs.Navigator tabBarActiveTintColor={accent} sidebarAdaptable minimizeBehavior="onScrollDown">
      <Tabs.Screen
        name="tab:home"
        component={HomeTab}
        options={{
          title: t(I18n.mobile.tabs.home),
          tabBarIcon: () => Icons.House.native,
          tabBarButtonTestID: "tab-home",
        }}
      />
      {can(Commerce.permissions.Order.read) ? (
        <Tabs.Screen
          name="tab:orders"
          component={OrdersTab}
          options={{
            title: t(I18n.mobile.tabs.orders),
            tabBarIcon: () => Icons.Package.native,
            tabBarButtonTestID: "tab-orders",
          }}
        />
     ) : null}
      <Tabs.Screen
        name="tab:settings"
        component={SettingsTab}
        options={{
          title: t(I18n.mobile.tabs.settings),
          tabBarIcon: () => Icons.Settings.native,
          tabBarButtonTestID: "tab-settings",
        }}
      />
    </Tabs.Navigator>
 );
}

/**
 * The whole tree; the session and the layout's `guard` pick the signed-in or the signed-out stack.
 */
export function Navigation() {
  const { t } = useTranslation();
  const session = useSession();
  const can = usePermission();
  const quickOrder = useFlag(Flags.orders.quick_order); // scan.route.ts `flag`
  // a redirect switches to the signed-out stack and keeps the link to resume
  const guard = useLayoutGuard(TabsLayout);

  if (session.status !== SessionStatus.SignedIn || guard.redirected)
    return (
      <SignedOut.Navigator screenOptions={{ headerShown: false }}>
        <SignedOut.Screen name="sign_in" component={toScreen(routeTable.sign_in)} />
      </SignedOut.Navigator>
   );

  return (
    <Root.Navigator screenOptions={glass}>
      <Root.Screen name="tabs" component={TabsShell} options={{ headerShown: false }} />
      {can(Commerce.permissions.Order.read) ? (
        <Root.Screen
          name="order_detail"
          component={toScreen(routeTable.order_detail)}
          options={{ title: t(I18n.mobile.order.title) }}
        />
     ) : null}
      {can(Commerce.permissions.Order.create) ? (
        <Root.Screen
          name="create_order"
          component={toScreen(routeTable.create_order)}
          options={{ ...formSheet, title: t(I18n.mobile.create_order.title) }}
        />
     ) : null}
      {can(Commerce.permissions.Product.read) && quickOrder ? (
        <Root.Screen
          name="scan"
          component={toScreen(routeTable.scan)}
          options={{ ...fullScreenModal, title: t(I18n.mobile.scan.title) }}
        />
     ) : null}
      <Root.Screen
        name="announcements"
        component={toScreen(routeTable.announcements)}
        options={{ title: t(I18n.mobile.announcements.title) }}
      />
      <Root.Screen
        name="inbox"
        component={toScreen(routeTable.inbox)}
        options={{ title: t(I18n.mobile.inbox.title) }}
      />
      <Root.Screen
        name="notification_preferences"
        component={toScreen(routeTable.notification_preferences)}
        options={{ title: t(I18n.mobile.notification_preferences.title) }}
      />
      <Root.Screen
        name="profile"
        component={toScreen(routeTable.profile)}
        options={{ title: t(I18n.mobile.profile.title) }}
      />
    </Root.Navigator>
 );
}
